,"floral":1,"woody":0,"powdery":0,"clean":6,"darkness":0,"strangeness":1,"intensity":5,"longevity":2,"is_featured":false,"display_order":5,"status":"active"},{"slug":"grapefruit","legacy_library_id":"grapefruit","legacy_bench_id":"grapefruit","category_slug":"citrus","name":"Grapefruit","material_type":"Note","family":"Citrus","layers":["top"],"tags":["sparkling","fresh","bright","grapefruit"],"moods":["Bitter","Sparkling","Modern"],"description":"Grapefruit is bright but distinctly bitter, with a pithy peel freshness that feels modern and clean. It keeps sweetness under control.","best_used_for":["Modern fresh perfumes","Dry citrus openings","Sporty clean structures","Balancing sweet fruit notes"],"pairs_well_with":["Vetiver","Cedarwood","Mint","Green Tea","Blackcurrant","White Musk"],"avoid_if":["You dislike pithy bitterness or dry sparkling citrus"],"image_path":"assets/library/citrus-icons/citrus-grapefruit.webp","image_alt":"Grapefruit material illustration","freshness":9,"sweetness":2,"warmth":1,"green":3,"floral":1,"woody":0,"powdery":0,"clean":6,"darkness":0,"strangeness":1,"intensity":5,"longevity":2,"is_featured":false,"display_order":6,"status":"active"},{"slug":"yuzu","legacy_library_id":"yuzu","legacy_bench_id":"yuzu","category_slug":"citrus","name":"Yuzu","material_type":"Note","family":"Citrus","layers":["top"],"tags":["sparkling","fresh","bright","yuzu"],"moods":["Luminous","Watery","Japanese"],"description":"Yuzu sits between lemon, mandarin, and grapefruit: bright, aromatic, slightly floral, and watery. It gives a refined citrus shimmer rather than simple sweetness.","best_used_for":["Transparent citrus openings","Tea and spa-like scents","Watery fresh perfumes","Minimal elegant formulas"],"pairs_well_with":["Green Tea","Shiso","Sea Salt","White Musk","Hinoki","Ginger"],"avoid_if":["You dislike airy, tart, or slightly bitter citrus freshness"],"image_path":"assets/library/citrus-icons/citrus-yuzu.webp","image_alt":"Yuzu material illustration","freshness":9,"sweetness":2,"warmth":1,"green":3,"floral":1,"woody":0,"powdery":0,"clean":6,"darkness":0,"strangeness":1,"intensity":5,"longevity":2,"is_featured":false,"display_order":7,"status":"active"},{"slug":"citron","legacy_library_id":"citron","legacy_bench_id":"citron","category_slug":"citrus","name":"Citron","material_type":"Note","family":"Citrus","layers":["top"],"tags":["sparkling","fresh","bright","citron"],"moods":["Textured","Peel-like","Clear"],"description":"Citron is less juicy and more peel-focused. It brings a dry, textured citrus brightness with a rind-like clarity that feels clean and architectural.","best_used_for":["Structured citrus openings","Dry fresh compositions","Cologne-style lift","Adding peel texture"],"pairs_well_with":["Petitgrain","Neroli","Lavender","Cedarwood","Vetiver","White Musk"],"avoid_if":["You dislike dry peel, rind bitterness, or less juicy citrus effects"],"image_path":"assets/library/citrus-icons/citrus-citron.webp","image_alt":"Citron material illustration","freshness":9,"sweetness":2,"warmth":1,"green":3,"floral":1,"woody":0,"powdery":0,"clean":6,"darkness":0,"strangeness":1,"intensity":5,"longevity":2,"is_featured":false,"display_order":8,"status":"active"},{"slug":"tangerine","legacy_library_id":"tangerine","legacy_bench_id":"tangerine","category_slug":"citrus","name":"Tangerine","material_type":"Note","family":"Citrus","layers":["top"],"tags":["sparkling","fresh","bright","tangerine"],"moods":["Sweet","Playful","Soft"],"description":"Tangerine is sweeter and more playful than mandarin, with a soft candy-peel brightness. It gives easy charm without becoming heavy.","best_used_for":["Playful citrus openings","Fruity fresh scents","Soft floral brightness","Gentle gourmand accents"],"pairs_well_with":["Peach","Orange Blossom","Vanilla","White Musk","Pear","Tonka Bean"],"avoid_if":["You dislike sweeter citrus or want a very dry opening"],"image_path":"assets/library/citrus-icons/citrus-tangerine.webp","image_alt":"Tangerine material illustration","freshness":9,"sweetness":2,"warmth":1,"green":3,"floral":1,"woody":0,"powdery":0,"clean":6,"darkness":0,"strangeness":1,"intensity":5,"longevity":2,"is_featured":false,"display_order":9,"status":"active"},{"slug":"kaffir-lime","legacy_library_id":"kaffir-lime","legacy_bench_id":"kaffir_lime","category_slug":"citrus","name":"Kaffir Lime","material_type":"Note","family":"Citrus","layers":["top"],"tags":["zesty","leafy","sharp","kaffir","lime"],"moods":["Leafy","Aromatic","Sharp"],"description":"Kaffir Lime is greener and more aromatic than regular lime, with a leafy, almost herbal edge. It creates a vivid botanical freshness.","best_used_for":["Botanical citrus openings","Green aromatic scents","Herbal tea concepts","Tropical leaf accents"],"pairs_well_with":["Basil","Shiso","Mint","Green Tea","Vetiver","Galbanum"],"avoid_if":["You dislike leafy, herbal, or sharply green citrus notes"],"image_path":"assets/library/citrus-icons/citrus-kaffir-lime.webp","image_alt":"Kaffir Lime material illustration","freshness":9,"sweetness":2,"warmth":1,"green":6,"floral":1,"woody":0,"powdery":0,"clean":6,"darkness":0,"strangeness":3,"intensity":5,"longevity":2,"is_featured":false,"display_order":10,"status":"active"},{"slug":"neroli","legacy_library_id":"neroli","legacy_bench_id":"neroli","category_slug":"citrus","name":"Neroli","material_type":"Note","family":"Citrus","layers":["top","heart"],"tags":["orange blossom","clean","luminous","neroli"],"moods":["Floral","Clean","Luminous"],"description":"Neroli comes from bitter orange blossom and feels both citrusy and floral. It adds clean radiance, soap-like elegance, and a refined Mediterranean brightness.","best_used_for":["Citrus-floral hearts","Cologne structures","Clean elegant perfumes","Soft white-floral freshness"],"pairs_well_with":["Bergamot","Petitgrain","Orange Blossom","Lavender","White Musk","Green Tea"],"avoid_if":["You dislike soapy floral brightness or classic clean cologne character"],"image_path":"assets/library/citrus-icons/citrus-neroli.webp","image_alt":"Neroli material illustration","freshness":9,"sweetness":2,"warmth":1,"green":3,"floral":7,"woody":0,"powdery":0,"clean":7,"darkness":0,"strangeness":1,"intensity":5,"longevity":2,"is_featured":false,"display_order":11,"status":"active"},{"slug":"petitgrain","legacy_library_id":"petitgrain","legacy_bench_id":"petitgrain","category_slug":"citrus","name":"Petitgrain","material_type":"Note","family":"Citrus","layers":["top"],"tags":["twig","bitter","green","petitgrain"],"moods":["Leafy","Bitter","Green"],"description":"Petitgrain is distilled from citrus leaves and twigs, so it is greener, woodier, and more bitter than fruit peel. It gives structure and natural freshness.","best_used_for":["Green citrus structures","Aromatic colognes","Balancing sweet orange notes","Adding leafy dryness"],"pairs_well_with":["Bergamot","Neroli","Lavender","Cedarwood","Vetiver","Green Tea"],"avoid_if":["You dislike bitter green leaves, twig-like dryness, or aromatic cologne facets"],"image_path":"assets/library/citrus-icons/citrus-petitgrain.webp","image_alt":"Petitgrain material illustration","freshness":9,"sweetness":0,"warmth":1,"green":7,"floral":1,"woody":2,"powdery":0,"clean":6,"darkness":0,"strangeness":1,"intensity":5,"longevity":2,"is_featured":false,"display_order":12,"status":"active"}]$materials$::jsonb)
